import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Retro — BATCH_NORM_RULES admission sweep: truth green, pay refuses","description":"","frontmatter":{"title":"Retro — `BATCH_NORM_RULES` admission sweep: truth green, pay refuses","type":"retro","date":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/bn-admission-sweep.md","filePath":"vendored/graphopt/project/retros/bn-admission-sweep.md"}'),a={name:`graphopt/project/retros/bn-admission-sweep.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-—-batch-norm-rules-admission-sweep-truth-green-pay-refuses" tabindex="-1">Retro — <code>BATCH_NORM_RULES</code> admission sweep: truth green, pay refuses <a class="header-anchor" href="#retro-—-batch-norm-rules-admission-sweep-truth-green-pay-refuses" aria-label="Permalink to “Retro — BATCH_NORM_RULES admission sweep: truth green, pay refuses”">​</a></h1><p><strong>Object</strong>: the three eval-mode expansion laws (<code>batch_norm_expand</code>, <code>batch_norm_expand_nobias</code>, <code>batch_norm_expand_plain</code>, <code>mlopt_core/laws/tensor.py</code>), held out of <code>DEFAULT</code> pending the guarded sweep — the same gauntlet the promoted laws cleared (<code>admission-gauntlet.md</code>, <code>mul-unsq-nat.md</code>).</p><p><strong>Verdict: NOT admitted.</strong> The sweep ran green through stage 4 (truth) and refused at stage 6 (typed-pay). <code>DEFAULT</code> unchanged — the sweep is the floor and it refused.</p><h2 id="how-it-ran" tabindex="-1">How it ran <a class="header-anchor" href="#how-it-ran" aria-label="Permalink to “How it ran”">​</a></h2><p>The gauntlet operates on <em>stored</em> objects, so each rule was stored verbatim (<code>store_object</code>, <code>kind=&quot;law&quot;</code>, <code>cert=None</code> — all three serialize fully: <code>missing_hooks</code> empty, <code>serializable: True</code>) into a scratch store <code>mlopt_discovery.cache_dir()/bn_admission.db</code>, then <code>run_gauntlet(key, corpus=default_gauntlet_corpus())</code>. The real corpus assembled in 10.1 s (364 real terms / 245 probe cases / 83 base rules); each gauntlet ran 0.6–9.9 s — the sweep is cheap on this box, no bounding needed.</p><h2 id="stage-account-all-three" tabindex="-1">Stage account (all three) <a class="header-anchor" href="#stage-account-all-three" aria-label="Permalink to “Stage account (all three)”">​</a></h2><table tabindex="0"><thead><tr><th>stage</th><th><code>batch_norm_expand</code></th><th><code>…_nobias</code></th><th><code>…_plain</code></th></tr></thead><tbody><tr><td>reconstruct</td><td>pass</td><td>pass</td><td>pass</td></tr><tr><td>full-data</td><td>pass</td><td>pass</td><td>pass</td></tr><tr><td>measure</td><td>matches=10 census=3</td><td>matches=0</td><td>matches=0</td></tr><tr><td>truth</td><td>synth 16eq/0ne/0rerr (344 declined, 360 envs); real 10eq/0ne</td><td>synth 16eq/0ne; real —</td><td>synth 16eq/0ne; real —</td></tr><tr><td>novelty</td><td>new</td><td>new</td><td>new</td></tr><tr><td><strong>typed-pay</strong></td><td><strong>FAIL — fires=8 typed=8 ill=0 paid=0</strong></td><td><strong>FAIL — fires=0</strong></td><td><strong>FAIL — fires=0</strong></td></tr></tbody></table><h2 id="why-the-refusal-is-the-honest-one" tabindex="-1">Why the refusal is the honest one <a class="header-anchor" href="#why-the-refusal-is-the-honest-one" aria-label="Permalink to “Why the refusal is the honest one”">​</a></h2><p>The truth gate is exactly what the family needed to clear: every guard-accepted evaluable binding is <code>equal</code> (16/16 synthesized, 10/10 real for the full variant; the two short arities accept nothing real because aten exports always carry the affine operands — their guarded region is corpus-empty but the sweep is not vacuous: 16 equal synth sites each).</p><p>The refusal is <code>typed-pay</code> (<code>evd.paid &gt; 0</code> required): the expand direction writes the fused kernel&#39;s <em>spelled</em> work into the e-graph — a member that is never the cheapest (<code>batch_norm</code> prices 4 vs the ~7-pass spelled subgraph, <code>tensor.py</code>&#39;s own header comment). On the 8 corpus sites the full variant fires, extraction never selects the member — <code>paid=0</code>. <code>nobias</code>/<code>plain</code> match no corpus arity at all (<code>fires=0</code>).</p><p>An expose/infrastructure law that cannot win extraction anywhere is not a <code>DEFAULT</code> candidate under this floor — the promoted laws each paid ≥1 site. Its value is <em>enabling</em>: it gives downstream weight-space laws the spelled per-channel scale/shift to see (<code>conv-bn-fold-synth.md</code>&#39;s anchor story). Admission routes that recognize enablement rather than extraction pay would be a different, unbuilt floor — recording the gate&#39;s verdict, not working around it.</p><h2 id="what-stays-open" tabindex="-1">What stays open <a class="header-anchor" href="#what-stays-open" aria-label="Permalink to “What stays open”">​</a></h2><ul><li><code>BATCH_NORM_RULES</code> remains opt-in (<code>search(..., rules=DEFAULT + BATCH_NORM_RULES)</code>); re-run the gauntlet if a corpus grows <code>batch_norm</code>-free export arities or an enablement-aware admission floor is built.</li><li>The <code>batch_norm_expand</code> matches (10) live in the corpus — the real BN sites exist (<code>ResNetBlock</code> et al.), so the family&#39;s <em>truth</em> was measured on real instances, not only synthesized ones.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};